// Разбор каналов YouTube (23.10): лист «Каналы для разбора» — Ссылка | Группа | Сколько роликов | Статус.
// Берём строки без статуса. Ссылка — канал (@имя, /channel/UC…, /user/…, /c/…) или любой ролик канала.
// Группа — любая метка автора («классика», «джаз», «кулинария»): по ней потом разбор, коду она не важна.
const API = 'https://www.googleapis.com/youtube/v3/';
const MAX_PER_RUN = 10;
function parse(raw) {
  const s = String(raw || '').trim();
  if (!s) return null;
  let m;
  if ((m = s.match(/(?:v=|youtu\.be\/|\/shorts\/|\/live\/|\/embed\/)([A-Za-z0-9_-]{11})/))) return { kind: 'video', value: m[1] };
  if ((m = s.match(/\/channel\/(UC[A-Za-z0-9_-]{22})/)) || (m = s.match(/^(UC[A-Za-z0-9_-]{22})$/))) return { kind: 'id', value: m[1] };
  if ((m = s.match(/(?:^|\/)@([^/?#\s]+)/))) return { kind: 'handle', value: '@' + decodeURIComponent(m[1]) };
  if ((m = s.match(/\/user\/([^/?#\s]+)/))) return { kind: 'user', value: m[1] };
  if ((m = s.match(/\/c\/([^/?#\s]+)/))) return { kind: 'custom', value: decodeURIComponent(m[1]) };
  if (/^[\w.-]+$/.test(s)) return { kind: 'handle', value: '@' + s };
  return null;
}
const url = p => p.kind === 'video' ? `${API}videos?part=snippet&id=${p.value}`
  : p.kind === 'id' ? `${API}channels?part=id&id=${p.value}`
  : p.kind === 'handle' ? `${API}channels?part=id&forHandle=${encodeURIComponent(p.value)}`
  : p.kind === 'user' ? `${API}channels?part=id&forUsername=${encodeURIComponent(p.value)}`
  : `${API}search?part=snippet&type=channel&maxResults=1&q=${encodeURIComponent(p.value)}`;
const out = [];
for (const it of $input.all()) {
  const r = it.json || {};
  const link = String(r['Ссылка'] || '').trim();
  if (!link || String(r['Статус'] || '').trim()) continue;
  const limit = Math.max(1, Math.min(50, parseInt(r['Сколько роликов'], 10) || 50));
  const p = parse(link);
  out.push({ json: { link, group: String(r['Группа'] || '').trim(), limit, kind: p ? p.kind : 'bad', step1Url: p ? url(p) : '' } });
  if (out.length >= MAX_PER_RUN) break;
}
return out;

// Из ответа YouTube — id канала (по видео, по имени, по поиску).
const prev = $('Что разбираем').all();
return $input.all().map((it, i) => {
  const src = prev[i].json, r = it.json || {}, x = (r.items || [])[0];
  const channelId = !x ? '' : (src.kind === 'video' || src.kind === 'custom') ? ((x.snippet || {}).channelId || '') : (x.id || '');
  const error = src.kind === 'bad' ? 'не понимаю ссылку' : r.error ? 'YouTube: ' + String((r.error.message || r.error)).slice(0, 150) : channelId ? '' : 'канал не найден';
  return { json: { ...src, channelId, error,
    chUrl: channelId ? `https://www.googleapis.com/youtube/v3/channels?part=snippet,statistics,contentDetails,brandingSettings&id=${channelId}` : '' } };
});

// Канал → его плейлист «все загрузки» → последние N роликов.
const prev = $('Есть канал?').all();
return $input.all().map((it, i) => {
  const src = prev[i].json, ch = ((it.json || {}).items || [])[0] || null;
  const uploads = ch && ch.contentDetails && ch.contentDetails.relatedPlaylists ? ch.contentDetails.relatedPlaylists.uploads : '';
  return { json: { ...src, channel: ch, error: ch ? '' : 'канал не открылся',
    plUrl: uploads ? `https://www.googleapis.com/youtube/v3/playlistItems?part=contentDetails&maxResults=${src.limit}&playlistId=${uploads}` : '' } };
});

const prev = $('Ролики: запрос списка').all();
return $input.all().map((it, i) => {
  const src = prev[i].json;
  const ids = ((it.json || {}).items || []).map(x => (x.contentDetails || {}).videoId).filter(Boolean);
  return { json: { ...src, videoIds: ids,
    vUrl: ids.length ? `https://www.googleapis.com/youtube/v3/videos?part=snippet,statistics,contentDetails&id=${ids.join(',')}` : '' } };
});

// общее для строк разбора
function isoMin(d) { const m = String(d || '').match(/P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/); if (!m) return 0; return Math.round(((+m[1] || 0) * 1440 + (+m[2] || 0) * 60 + (+m[3] || 0) + (+m[4] || 0) / 60) * 10) / 10; }
function hashtags(t) { return [...new Set(String(t || '').match(/#[\p{L}\p{N}_]+/gu) || [])]; }
function median(a) { const s = a.filter(x => x != null && !isNaN(x)).sort((x, y) => x - y); if (!s.length) return ''; const k = Math.floor(s.length / 2); return s.length % 2 ? s[k] : Math.round((s[k - 1] + s[k]) / 2); }
function today() { const d = new Date(); return String(d.getUTCDate()).padStart(2, '0') + '.' + String(d.getUTCMonth() + 1).padStart(2, '0') + '.' + d.getUTCFullYear(); }
function chLink(ch) { const h = ((ch || {}).snippet || {}).customUrl; return h ? 'https://www.youtube.com/' + (h.startsWith('@') ? h : '@' + h) : 'https://www.youtube.com/channel/' + ((ch || {}).id || ''); }

// Строка на ролик → лист «Разбор: ролики».
const prev = $('Ролики: запрос данных').all();
const out = [];
$input.all().forEach((it, i) => {
  const src = prev[i].json, ch = src.channel || {};
  for (const v of ((it.json || {}).items || [])) {
    const sn = v.snippet || {}, st = v.statistics || {}, cd = v.contentDetails || {};
    const desc = String(sn.description || '');
    const tags = sn.tags || [];
    const th = sn.thumbnails || {};
    out.push({ json: {
      'Группа': src.group, 'Канал': (ch.snippet || {}).title || '', 'Ссылка на канал': chLink(ch),
      'Ролик': 'https://www.youtube.com/watch?v=' + v.id, 'Название': sn.title || '', 'Длина названия': String(sn.title || '').length,
      'Дата': String(sn.publishedAt || '').slice(0, 10), 'Минут': isoMin(cd.duration),
      'Просмотры': +st.viewCount || 0, 'Лайки': +st.likeCount || 0, 'Комментарии': +st.commentCount || 0,
      'Тегов': tags.length, 'Теги': tags.join(', '), 'Хэштеги': hashtags(desc).join(' '),
      'Начало описания': desc.split('\n').filter(l => l.trim()).slice(0, 2).join(' / ').slice(0, 300),
      'Длина описания': desc.length, 'Описание': desc.slice(0, 5000),
      'Язык': sn.defaultAudioLanguage || sn.defaultLanguage || '', 'Категория': sn.categoryId || '',
      'Обложка': (th.maxres || th.high || th.medium || th.default || {}).url || '', 'Разобрано': today(),
    } });
  }
});
return out;

